<script>
import DataService from '../../service/DataService'
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
import DisplayOldAndNewUnique from './DisplayOldAndNewUnique.vue';
export default {
    components: {
        'tree-view': Treeselect,
        DisplayOldAndNewUnique
    },
    props: {
        filepath: {
            type: String,
        }
    },
    data() {
        return {
            AssetType: [],
            StatusListData: [],
            BarcodeType: [],
            AuditData: [],
            ImageCaptureData: [],
            AssetFrequencyList: [],
            CalibrationData: [],
            LocationValue: null,
            options: [],
            dData: [],
            UserId: '',
            CompanyId: '',
            ExcelListData: [],
            ProductType: [],
            StatusData: [],
            BarcodeData: [],
            AuditRecord: [],
            ImageCaptureRecord: [],
            CalibrationRecord: [],
            DepreciationRecord: [],
            LocationData: [],
            popover: {
                visibility: 'click'
            },
            Loading: false,
            duplicatesChecked: false,
            duplicateNames: new Set(),
            duplicateNewItemNames: new Set(),
            Xdata: [],
            conflicts: [],
            isShowUniqueItemPopup: false,
            currentConflicts: [],
            conflictType: '',
            serialDuplicates: [],
            serialChecked: false
        }
    },
    async created() {
        this.UserId = this.GetUserInfo.ID;
        this.CompanyId = this.GetUserInfo.CompanyId;
        await this.GetAssetTypeCustom();
        await this.ImportItems();
        await this.GetBarcodeType();
        await this.GetStatusList()
        await this.GetAssetFrequency();
        await this.GetLocationByCompanyId();
        await this.GetDepreciationRule();
        await this.GetLocationByCompanyId1();
    },
    methods: {

        handleProductNameInput(item, index) {
            item.isDuplicateProduct = false;
            this.duplicatesChecked = false;
        },
         handleParentAssetNameInput(item, index) {
            item.isProductExist = false;
        },

        handleItemNameInput(item, index) {
            item.isDuplicate = false;
            item.isOldDuplicate = false;

            // Recheck for duplicates across Xdata (exclude self via index)
            const currentName = item.Item_Name?.trim().toUpperCase();
            const hasDuplicate = this.Xdata.some((row, rowIndex) =>
                rowIndex !== index &&
                row.Item_Name?.trim().toUpperCase() === currentName
            );

            if (hasDuplicate) {
                this.ShowAlert(this.$t("ExistingItemName"), 'failure');
                item.Item_Name = '';
                // item.isDuplicate = true;  // Re-flag for highlight
                return;
            }
            const upperName = item.Item_Name?.trim().toUpperCase();
            if (upperName && this.duplicateNames.has(upperName)) {
                this.duplicateNames.delete(upperName);
            }

            this.duplicatesChecked = false;
        },

        handleNewItemNameInput(item, index) {
            item.isDuplicateNewItem = false;
            item.isNewDuplicate = false;



            const upperName = item.New_Item_Name?.trim().toUpperCase();
            if (upperName && this.duplicateNewItemNames.has(upperName)) {
                this.duplicateNewItemNames.delete(upperName);
            }

            this.duplicatesChecked = false;
        },

        handleQuantityInput(item, index) {
            const conflict = this.conflicts.find(c => c.product_name.trim().toLowerCase() == item.Product_Name?.trim().toLowerCase());

            if (conflict && conflict.productUniqueOrNonUniqueStatus === true) {
                const quantity = parseFloat(item.Quantity) || 0;
                if (quantity > 1) {
                    // item.Quantity = 1;
                    item.isQuantityHighlighted = true;
                } else if (quantity <= 1 && quantity > 0) {
                    item.isQuantityHighlighted = false;
                } else {
                    item.Quantity = '';
                    item.isQuantityHighlighted = false;
                }
            } else {
                const quantity = parseFloat(item.Quantity) || 0;
                item.Quantity = quantity > 0 ? quantity : '';
                item.isQuantityHighlighted = false;
            }
        },

        handleSerialNumberInput(item, index) {
            item.isSerialDuplicate = false;
            this.serialChecked = false;
        },
        handleMacAddressInput(item, index) {
            item.isMacDuplicate = false;
        },
        onEyeClick(item, index, type) {
            this.conflictType = type;
            if (type === 'old') {
                // Show old item name conflicts
                if (item.oldConflicts && item.oldConflicts.length > 0) {
                    this.currentConflicts = item.oldConflicts;
                    this.isShowUniqueItemPopup = true;
                } else {
                    this.currentConflicts = [];
                    this.isShowUniqueItemPopup = false;
                }
            } else if (type === 'new') {
                // Show new item name conflicts
                if (item.newConflicts && item.newConflicts.length > 0) {
                    this.currentConflicts = item.newConflicts;
                    this.isShowUniqueItemPopup = true;
                } else {
                    this.currentConflicts = [];
                    this.isShowUniqueItemPopup = false;
                }


                this.currentConflicts = item.newConflicts || [];
            }
        },

        closeUniquePopup() {
            this.isShowUniqueItemPopup = false;
            this.currentConflicts = [];
            this.conflictType = '';
        },


        async checkProductNameDuplicates() {

            if (!this.Xdata || this.Xdata.length === 0) return false;

            const productNames = [...new Set(
                this.Xdata
                    .filter(i => i.Product_Name && i.Product_Name.trim())
                    .map(i => i.Product_Name.trim().toLowerCase())
            )];

            if (productNames.length === 0) return false;

            try {
                const payload = { ItemNames: productNames };

                const response = await DataService.CheckBulkProductName(payload);
                // Store conflicts for quantity enforcement
                this.conflicts = response.data.conflicts || [];

                this.Xdata.forEach((item, index) => {

                    const conflict = this.conflicts.find(c => c.product_name.trim().toLowerCase() == item.Product_Name?.trim().toLowerCase());
                    if (conflict && conflict.productUniqueOrNonUniqueStatus === true) {
                        item.hasUniqueNames = true;
                    } else {
                        item.hasUniqueNames = false;
                    }
                });

                if (response?.data?.notFoundProducts?.length > 0) {

                    const validNamesUpper = response.data.notFoundProducts.map(
                        c => c.product_name.trim().toUpperCase()
                    );

                    let hasMatch = false;

                    this.Xdata.forEach(item => {
                        const itemUpper = item.Product_Name?.trim().toUpperCase();

                        // 👉 YOUR RULE:
                        // if name exists in validNamesUpper → ERROR
                        if (itemUpper && validNamesUpper.includes(itemUpper)) {
                            item.isDuplicateProduct = true;   // highlight
                            item.hasUniqueNames = null;
                            hasMatch = true;
                        } else {
                            item.isDuplicateProduct = false;
                        }
                    });

                    return hasMatch;

                } else {
                    this.Xdata.forEach(item => item.isDuplicateProduct = false);
                    return false;
                }



            } catch (error) {
                console.error('Bulk product check failed:', error);
                return true; // fail-safe: block submission
            }
        },

        async checkParentAssetDuplicates() {
            if (!this.Xdata || this.Xdata.length === 0) return false;

            const parentAssets = [...new Set(
                this.Xdata
                    .filter(i => i.parent_asset && i.parent_asset.trim())
                    .map(i => i.parent_asset.trim().toLowerCase())
            )];

            if (parentAssets.length === 0) return false;

            try {
                const payload = { ItemNames: parentAssets };

                const response = await DataService.CheckBulkProductName(payload);
                if (response?.data?.notFoundProducts?.length > 0) {

                    const validNamesUpper = response.data.notFoundProducts.map(
                        c => c.product_name.trim().toUpperCase()
                    );

                    let hasMatch = false;

                    this.Xdata.forEach(item => {
                        const itemUpper = item.parent_asset?.trim().toUpperCase();

                        if (itemUpper && validNamesUpper.includes(itemUpper)) {
                            item.isProductExist = true;
                            hasMatch = true;
                        } else {
                            item.isProductExist = false;
                        }
                    });

                    return hasMatch;

                } else {
                    this.Xdata.forEach(item => item.isProductExist = false);
                    return false;
                }

            } catch (error) {
                console.error('Bulk parent asset check failed:', error);
                return true; // fail-safe: block submission
            }
        },



        // Call your bulk rename API first
        async validateBulkRename() {
            if (this.Xdata.length === 0) return false;

            try {

                this.Xdata.forEach((item, index) => {
                    item.oldConflicts = []
                    item.newConflicts = []
                });


                const payload = {
                    Items: this.Xdata.map(item => ({
                        product_name: item.Product_Name,
                        old_item_unique_name: item.Item_Name || '',
                        new_item_unique_name: item.New_Item_Name || ''
                    })),
                    Count: 1
                };

                const response = await DataService.CheckBulkItemName(payload);  // Your endpoint

                // Process results row-by-row
                let hasDuplicates = false;
                response.data.results.forEach((result, index) => {  // Note: Results (capital R)
                    const row = this.Xdata[index];

                    // Old name issues
                    row.isOldDuplicate = result.is_olditem_duplicate;
                    if (result.is_olditem_duplicate) {
                        row.oldConflicts = result.old_duplicate_items_json ?
                            JSON.parse(result.old_duplicate_items_json) : [];
                        hasDuplicates = true;
                    }

                    // New name issues  
                    row.isNewDuplicate = result.is_newitem_duplicate;
                    if (result.is_newitem_duplicate) {
                        row.newConflicts = result.new_duplicate_items_json ?
                            JSON.parse(result.new_duplicate_items_json) : [];
