        async validateSerialNumbers() {
            if (this.Xdata.length === 0) return false;

            // Get items with serial numbers
            const itemsWithSerials = this.Xdata.filter(item =>
                item.Serial_Number && item.Serial_Number.trim() !== ''
            );

            if (itemsWithSerials.length === 0) return false;

            try {
                // Prepare payload for API
                const payload = {
                    Items: itemsWithSerials.map(item => ({
                        product_name: item.Product_Name || '',
                        item_name: item.Item_Name || '',
                        serial_number: item.Serial_Number || ''
                    }))
                };

                const response = await DataService.CheckBulkItemSerials(payload);

                // API returns { results: [...] }
                this.serialDuplicates = response.data?.results || [];

                let hasSerialDuplicates = false;

                // Reset flags
                this.Xdata.forEach(item => {
                    item.isSerialDuplicate = false;
                    item.serialDuplicateInfo = null;
                });

                // Mark items with duplicate serials
                this.Xdata.forEach(item => {
                    if (!item.Serial_Number || item.Serial_Number.trim() === '') return;

                    const duplicate = this.serialDuplicates.find(d =>
                        d.serial_number &&
                        d.serial_number.trim().toUpperCase() === item.Serial_Number.trim().toUpperCase()
                    );

                    // Note: is_serial_duplicate is BIT → comes as true/false from API
                    if (duplicate && duplicate.is_serial_duplicate) {
                        item.isSerialDuplicate = true;
                        item.serialDuplicateInfo = duplicate;
                        hasSerialDuplicates = true;
                    }
                });

                // Only return flag, no alert here
                return hasSerialDuplicates;

            } catch (error) {
                console.error('Serial number validation failed:', error);
                // On error, don't block save
                return false;
            }
        },
        

      async validateMacAddress() {
            if (this.Xdata.length === 0) return false;

            const itemsWithMacAddress = this.Xdata.filter(item =>
                item.mac_address && item.mac_address.trim() !== ''
            );

            if (itemsWithMacAddress.length === 0) return false;

            try {
                const payload = {
                    Items: itemsWithMacAddress.map(item => ({
                        product_name: item.Product_Name || '',
                        item_name: item.Item_Name || '',
                        mac_address: item.mac_address || ''
                    }))
                };

                // ✅ Correct API
                const response = await DataService.CheckBulkItemSerials(payload);
                this.macAddressDuplicates = response.data?.results || [];

                let hasMacAddressDuplicates = false;

                // ✅ reset flags
                this.Xdata.forEach(item => {
                    item.isMacDuplicate = false;
                    item.macDuplicateInfo = null;
                });

                // ✅ match using product_name + item_name (since mac not in response)
                this.Xdata.forEach(item => {
                    if (!item.mac_address || item.mac_address.trim() === '') return;

                    const duplicate = this.macAddressDuplicates.find(d =>
                        d.product_name?.trim().toUpperCase() === item.Product_Name?.trim().toUpperCase() &&
                        d.item_name?.trim().toUpperCase() === item.Item_Name?.trim().toUpperCase()
                    );

                    if (duplicate && duplicate.is_mac_address_duplicate) {
                        item.isMacDuplicate = true;
                        item.macDuplicateInfo = duplicate;
                        hasMacAddressDuplicates = true;
                    }
                });
                return hasMacAddressDuplicates;

            } catch (error) {
                console.error('MAC address validation failed:', error);
                return false;
            }
