        getLocationIdByName(name) {
            function searchTree(nodes) {
                for (const node of nodes) {
                    if (node.label.toLowerCase() === name.toLowerCase()) {
                        return node.id;
                    }
                    if (node.children && node.children.length > 0) {
                        const found = searchTree(node.children);
                        if (found) return found;
                    }
                }
                return null;
            }

            return searchTree(this.options);  // assuming `this.options` is your tree source
        },
