        async ImportItems() {
            const vm = this;

            if (!vm.filepath) {
                vm.ShowAlert(vm.$t("Filepath is missing"), "warning", vm.$t("Alert")); return;
            }

            vm.Loading = true;
            vm.showSlowMsg = false;

            vm.slowTimerId = setTimeout(() => { vm.showSlowMsg = true; }, 4000);
            const url = `filepath=${vm.filepath}&typeName='Product'`;
            try {
                const response = await DataService.BulkUploadItems(url);
                if (response.data != null) {

                    let hasError = false;

                    // First validate all records BEFORE mapping
                    for (const item of response.data) {
                        if (item.Messages?.trim() === '[ERROR]') {

                            if (item.ErrorMessage == null || item.ErrorMessage.trim() === '') {
                                vm.Loading = false;
                                hasError = true;
                                vm.ShowAlert(vm.$t("ValidExcelFile"), "failure", true, vm.$t("Alert"))
                                break;

                            }
                            let rawError = item.ErrorMessage || "";
                            // Split by newline and take the first line only
                            let firstLine = rawError.split("\n")[0].trim();
                            // Remove the exception type if present before the actual message
                            if (firstLine.includes(":")) {
                                firstLine = firstLine.substring(firstLine.indexOf(":") + 1).trim();
                            }

                            vm.ShowAlert(firstLine, "failure", true, vm.$t("Alert"));
                            hasError = true;
                            break;
                        }

                        if (!item.Product_Name?.trim() || !item.Item_Name?.trim()) {
                            vm.ShowAlert(vm.$t("ValidExcelFile"), "failure", vm.$t("Alert"));
                            hasError = true;
                            break;
                        }

                    }

                    // Stop processing if any validation failed
                    if (hasError) {
                        vm.Xdata = [];
                        return;
                    }

                    // Now transform the list safely using MAP
                    let hasQuantityAdjusted = false;
                    vm.Xdata = response.data.map(item => {

                        let parsedMessage = {};
                        if (item.Messages) {
                            try {
                                parsedMessage = JSON.parse(item.Messages);
                            } catch (e) {
                                console.error("Error parsing Messages:", e);
                            }
                        }
                        const isDuplicateProduct = parsedMessage.product_item_exists === "NotExists";
                        const isProductNotExists = parsedMessage.product_item_exists === "NotExists";
                        const hasUniqueNames = parsedMessage.product_has_unique_names;

                        const isProductExist = parsedMessage.parent_item_exists === "NotExists";
                        let quantity = parseFloat(item.Quantity) || 0;
                        // Apply quantity check for unique products - if unique and quantity > 1, set to 1
                        if (hasUniqueNames === true && quantity > 1) {

                            hasQuantityAdjusted = true;
                        }
                        const isQuantityHighlighted = hasUniqueNames === true && parseFloat(item.Quantity) > 1;

                        return {
                            ...item,
                            Quantity: quantity,
                            parsedMessage,
                            isDuplicateProduct,
                            isProductNotExists,
                            hasUniqueNames,
                            isQuantityHighlighted,
                            isOldDuplicate: false,
                            isNewDuplicate: false,
                            isProductExist,
                        };
                    });

                    // Show alert message if quantity was adjusted for any unique products
                    if (hasQuantityAdjusted) {
                        vm.ShowAlert(vm.$t("UniqueQuantityMessage"), "failure", vm.$t("Alert"));
                    }

                } else {
                    vm.ShowAlert(vm.$t("InValidFileUpload"), "warning", vm.$t("Alert"));
                }

            } catch (err) {
                console.error(err);
                vm.ShowAlert(vm.$t("ErrorWhileProcessingRequest"), "failure", vm.$t("Alert"));
            } finally {
                clearTimeout(vm.slowTimerId);
                vm.showSlowMsg = false;
                vm.Loading = false;
            }

        },

