<template>
    <div class="my-popups">
        <div class="modal-backdrop show" @click="closeModal"></div>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered modal-lg">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ type === 'old' ? 'Old Item Conflicts with below items' : 'New Item Conflicts with below items' }}
                        </h5>
                        <button type="button" class="close" @click="closeModal" data-original-title="Close">
                            <em class="fa fa-times"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <div v-if="conflicts.length === 0" class="text-center text-danger">
                            {{ $t("NoRecordfound") }}
                        </div>
                        <div v-else class="table-responsive">
                            <table class="table table-bordered">
                                <thead>
                                    <tr>
                                        <!-- <th>{{ $t('Id') }}</th> -->
                                        <th>{{ $t('UniqueName') }} </th>
                                        <th>{{ $t('ProductName') }}</th>
                                        <th>{{ $t('LOCATION') }}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="(conflict, index) in conflicts" :key="index">
                                        <!-- <td>{{ conflict.related_info_id }}</td> -->
                                        <td>{{ conflict.unique_name }}</td>
                                        <td>{{ conflict.catalogue_name }}</td>
                                        <td>{{ conflict.location_name }}</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
export default {
    props: {
        conflicts: {
            type: Array,
            default: () => []
        },
        type: {
            type: String,
            default: ''
        }
    },
    data() {

        return {


        }


    },
    created() {


    },

    methods: {
        closeModal() {
            this.$emit('close');
        }
    }
}
</script>
