<script>
import ImportProduct from '../../components/Modal/ImportProduct.vue'
import ImportItem from '../../components/Modal/ImportItem.vue'
import DataService from '../../service/DataService';

export default {
    components: {
        ImportProduct,
        ImportItem
    },
    data: function () {
        return {
            isLoading: false,
            file: null,
            filepath: '',
            excelFileName: null,
            excelFile: null,
            reqfrom: null,
            expListing: null,
            trips: [],
            categories: [],
            projects: [],
            currencies: [],
            tasks: [],
            expLimitJsonBack: [],
            check_EXPENSE_LIMIT: false,
            userDateFormat: null,
            files: new FormData(),
            value: null,
            attachmentName: '',
            fileName: '',
            ShowImportProduct: false,
            ShowImportItem: false,
        }
    },
    methods: {
        BackTolist: function () {
            this.$router.push({
                name: 'ProductListing'
            });
        },
        onCancel: function () {
            this.$router.push({
                name: 'ProductListing'
            });
        },
        setFile: function (e) {
            this.attachmentName = e.target.files[0].name;
            this.file = e.target.files[0];
            this.excelFileName = e.target.files[0].name;
        },
        setFiles: function (e) {
            this.fileName = e.target.files[0].name;
            this.file = e.target.files[0];
            this.excelFile = e.target.files[0].name;
        },
        Clear: function () {
            this.attachmentName = '';
        },
        Clear1() {
            this.$refs.fileInput.value = null;
            this.fileName = ''; // Clear the displayed file name
            this.file = null; // Clear the file object
            this.excelFile = null; // Clear the excel file name 
            //this.errors = []; // Reset any error messages
        },
        UploadProductSampleFile() {
            var vm = this;
            vm.$emit('ImportProduct')
            if ($("#flAvatar").val() != "") {
                var file = $("#flAvatar").val().split('\\').pop();
                var allowFileTypesExt = '.xls,.xlsx';
                var extension = file.replace(/^.*\./, '');
                if (!allowFileTypesExt.includes(extension)) {
                    vm.ShowAlert(vm.$t('InvalidSampleFileUploadMsg', [file, allowFileTypesExt]), "warning", true, vm.$t('Alert'));
                } else {
                    vm.confirmR(vm.$t("bulkImportConfirmationMsg"), true, (vm.$t("Delete") + "  " + vm.$t("REPORT_ID")), function () {
                        const formdata = new FormData();
                        formdata.append("file", vm.file);
                        vm.isLoading = true;
                        DataService.ImportProductSamplePost(formdata).then(function (response) {
                            vm.isLoading = false;
                            var data = response.data;
                            if (data.Status == 0) {
                                vm.filepath = data.Msg;
                                vm.ShowImportProduct = vm.filepath != '' ? true : false;
                            } else {
                                vm.ShowAlert(data.Msg, "warning", true, vm.$t("Alert"));
                            }
                        });
                        vm.isLoading = false;
                    });
                }
            } else {
                vm.ShowAlert(vm.$t("PleaseUploadExcelFile"), "warning", true, vm.$t("Alert"));
            }
        },
        UploadItemSampleFile() {
            var vm = this;
            vm.$emit('ImportItem')
            if ($("#ItemFile").val() != "") {
                var file = $("#ItemFile").val().split('\\').pop();
                var allowFileTypesExt = '.xls,.xlsx';
                var extension = file.replace(/^.*\./, '');
                if (!allowFileTypesExt.includes(extension)) {
                    vm.ShowAlert(vm.$t('InvalidSampleFileUploadMsg', [file, allowFileTypesExt]), "warning", true, vm.$t('Alert'));
                } else {
                    vm.confirmR(vm.$t("bulkImportConfirmationMsg"), true, (vm.$t("Delete") + "  " + vm.$t("REPORT_ID")), function () {
                        vm.ShowImportItem = false;
                        const formdata = new FormData();
                        formdata.append("file", vm.file);
                        if (formdata == {}) {
                            vm.Clear1();
                        }
                        vm.isLoading = true;
                        DataService.ImportItemSamplePost(formdata).then(function (response) {
                            vm.isLoading = false;
                            vm.filepath = '';
                            var data = response.data;
                            if (data.Status == 0) {
                                vm.filepath = data.Msg;
                                vm.ShowImportItem = vm.filepath != '' ? true : false;
                            } else {
                                vm.ShowAlert(data.Msg, "warning", true, vm.$t("Alert"));
                            }
                        });
                        vm.isLoading = false;
                    });
                }
            } else {
                vm.ShowAlert(vm.$t("PleaseUploadExcelFile"), "warning", true, vm.$t("Alert"));
            }
        },
    }
}
</script>
